/* Extended manuscript walkthroughs. Figure identifiers map to inspected PDF crops. */
(function(){
  'use strict';
  const M=window.__researchManuscripts, E=window.__researchPortfolio.esc;
  const P=(...text)=>text.map(t=>`<p>${t}</p>`).join('');
  const S=(title,html)=>({title,html});
  const note=t=>`<p class="rm-source">${t}</p>`;
  function F(paper,...keys){return keys.map(key=>{
    const f=window.__researchEvidenceData[paper][key];
    return `<figure class="rm-evidence" data-evidence="${paper}/${key}"><div class="rm-evidence-heading"><span>${E(f.label)}</span><h3>${E(f.title)}</h3></div><button type="button" class="rm-figure-open" aria-label="Enlarge ${E(f.label)}: ${E(f.title)}"><img src="${f.src}" width="${f.width}" height="${f.height}" loading="lazy" decoding="async" alt="${E(f.label)}. ${E(f.title)}. Original manuscript, page${f.pages.length>1?'s':''} ${f.pages.join(', ')}."><span class="rm-enlarge" aria-hidden="true">↗ Enlarge</span></button><figcaption>Original manuscript · ${E(f.label)} · page${f.pages.length>1?'s':''} ${f.pages.join(', ')}. Click the image to inspect the full resolution.</figcaption></figure>`;
  }).join('');}
  const add=(id,i,html)=>M[id].sections[i].html+=html;
  const after=(id,title,...sections)=>{const n=M[id].sections.findIndex(s=>s.title===title);if(n<0)throw Error(title);M[id].sections.splice(n+1,0,...sections);};
  const steps=items=>`<ol class="rm-method-steps">${items.map(([h,t])=>`<li><h3>${h}</h3><p>${t}</p></li>`).join('')}</ol>`;
  const focus=(h,t)=>`<div class="rm-insight"><span>Reading the result</span><h3>${h}</h3>${P(t)}</div>`;

  add('jhe',0,P('The program creates a particularly useful link between payment incentives and market structure. A facility can change the services it offers, expand or contract capacity, enter, or close. Each of those choices can reshape the set of alternatives available to nearby residents. The study follows this supply response through physical locations and the road network, translating a national reimbursement policy into a local access outcome.', 'The randomized sample is reconstructed from CMS’s selected-region records. Four Maryland-rule inclusions are separated from the lottery, leaving 91 treated and 211 control HRRs. Within the four census regions, the treated counts are 25 of 84 in the Midwest, 13 of 43 in the Northeast, 35 of 115 in the South, and 18 of 60 in the West. Preserving that assignment structure ties the empirical comparison directly to the policy experiment.')+F('jhe','t1'));
  add('jhe',1,P('The pipeline joins three distinct systems. The supply side contains certified facility records; the demand side contains populated block groups and CKD-risk weights; the reference layers contain hospital referral regions, treatment assignment and roads. Each system has a separate role. Facilities determine the available destinations, demand weights determine how access is aggregated, and the fixed reference geography makes vintages comparable.', 'Site continuity is resolved before calculating entry and exit. Records at the same canonical address are linked, while nearby records require agreement in continuity fields. A single HRR assignment follows each linked site through time. The resulting panel supports both network outcomes and a second set of measures describing stations and home-dialysis services.')+F('jhe','fa2'));
  add('jhe',2,P('The map shows why geography is central to the research design. Baseline backup access differs sharply across regions. The treatment indicator is superimposed on that existing landscape, so the analysis uses each region’s starting access conditions to gain precision. A thin initial network has a different scope for change from a dense urban network.', 'The distribution of observed changes also establishes that the access measure responds to real network movement. Between baseline and the primary endpoint, 119 HRRs move by more than one percentage point and 48 move by more than five. Nationally, 8.5% of modeled CKD-risk mass lies within five minutes of the 30-minute threshold at baseline, and 2.1% crosses that threshold by the endpoint. These are economically active margins over which the randomized comparison is made.')+F('jhe','f1','f2'));
  add('jhe',3,P('Precision comes from using information that predates treatment. The primary estimator combines census-region stratification with arm-specific baseline slopes, while keeping the target population as an equally weighted set of randomized HRRs. This is useful because the policy lottery assigns regions, and the research question concerns the average region’s access response.', 'The variance reduction can be translated into the size of a policy effect the design can detect. The table and explorer below show the same relationship: better baseline prediction reduces the standard error and the minimum detectable effect together. At the realized 91.6% reduction, the design moves from a 9.14-point minimum detectable effect to 2.65 points.')+`<div class="rm-widget" data-depth-widget="precision"><h3>How much does baseline information buy?</h3><p>Trace the manuscript’s precision relationship from the unadjusted design to stronger baseline prediction.</p><label>Variance reduction: <output>91.6%</output><input type="range" min="0" max="95" step="0.1" value="91.6" aria-label="Variance reduction from baseline adjustment"></label><div class="rm-output" aria-live="polite"></div></div>`+F('jhe','ta2'));
  add('jhe',4,P('The endpoint table places the central estimate beside two deliberately different comparisons: the conventional unadjusted contrast and the extreme assignments of unresolved routing mass. Together they show the contribution of the statistical design and of the geographic measurement exercise. The confidence interval for each routing-bound estimate remains inside the pre-specified five-point materiality band.', 'The policy interpretation follows the interval. The study establishes that the average regional change is tightly bounded relative to a meaningful loss of backup access. The equivalence analysis turns a statistically small point estimate into a quantitative statement about the magnitude of supply adjustment supported by the experiment.')+F('jhe','t2'));
  add('jhe',5,P('A full access curve makes the result easier to assess. Each cutoff defines a different question: whether a nearby backup is available within a short trip, a conventional commuting radius, or a much longer journey. The analysis reconstructs the outcome at every integer cutoff from 10 through 60 minutes and uses the matching baseline outcome at that same cutoff.', 'Across the 51 thresholds, the adjusted point estimates run from −0.89 to +0.47 percentage points. A joint randomization procedure evaluates the whole curve. Its 95% simultaneous band uses a sup-t critical value of 2.55, with a largest half-width of 2.62 points. The appendix reports selected thresholds so the reader can connect the plotted curve to the individual estimates.')+F('jhe','f4','ta1'));
  add('jhe',6,P('The estimator comparison keeps track of both specification and target. Common-slope ANCOVA, arm-specific regression, change scores, region-specific estimates and CKD-mass weighting answer closely related questions with different constructions. Reporting them together shows how the endpoint conclusion behaves across those choices.', 'A leave-one-region-out exercise fits the primary estimator 302 times. Its point estimates remain between −1.05 and −0.35 percentage points. Removing the two HRRs with the weakest routing coverage also retains the equivalence result. The analysis thereby connects the national conclusion to individual-region influence and geographic data coverage.')+F('jhe','t3'));
  after('jhe','Building a panel of physical facilities',S('Following the national supply network',P('The linked records also reveal the level and composition of national supply. The count of eligible in-center physical sites rises early in the panel and then declines, while dialysis station capacity follows its own path. Separating sites from stations matters: a network can consolidate locations while retaining treatment capacity, or add stations without creating a new geographic alternative.', 'Figure A1 puts these two margins on a common timeline and marks the period when ETC operated. The randomized analysis then asks whether the regional changes differ by assignment. This connects descriptive industry evolution to a design-based policy comparison, while the physical-site reconstruction keeps administrative relabeling from being counted as economic entry.')+F('jhe','fa1')));
  after('jhe','A tightly bounded average effect',S('Tracing adjustment through time',P('The vintage-by-vintage estimates connect the primary endpoint to the entire period of observation. The adjusted contrast is close to zero early in the panel, then becomes modestly negative in later vintages. The November 2025 endpoint is followed by a July 2026 estimate, giving a view of the network after the model’s termination.', 'The figure uses the same outcome and regional comparison across vintages. Its point estimates and confidence intervals remain within the five-point materiality band. Reading the path alongside the endpoint helps distinguish gradual network movement from a sharp discontinuity associated with one measurement date.')+F('jhe','f3')+note('Manuscript §V.C and Figure 3.')));
  after('jhe','Stress-testing the policy conclusion',S('Reading access, capacity and service together',P('Travel time, station capacity and services connect the geographic result to providers’ operating choices. At the 2025 endpoint, mean second-site travel changes by +0.46 minutes and nearest-site travel by −0.23 minutes. These continuous measures complement the binary threshold outcome by tracking changes throughout the travel-time distribution.', 'The facility ledger adds closures, physical site counts and dialysis stations. At the national level, the network experiences substantial turnover; within the randomized comparison, the treatment-control difference in baseline-site closures is +0.29 percentage points. The study also follows peritoneal dialysis, home-hemodialysis training, late-shift services and reported modality availability.', 'Together, these measures give the supply-side interpretation its structure. The analysis follows where providers operate, how much physical treatment capacity remains, and which services are offered. The July 2026 vintage and the pooled late-period outcomes extend the comparison beyond the primary endpoint.')+F('jhe','t4','t5')),
    S('Mapping exposure across regional borders',P('Dialysis markets cross administrative boundaries. At baseline, 10.3% of the first two access slots for an average HRR are supplied by facilities in another HRR. Cross-border reliance exceeds 5% in 211 of the 302 analysis regions. The paper reconstructs this relationship from the same origin-to-facility routes used in the access outcomes.', 'The treated-neighbor measure weights neighboring treatment assignment by the share of a region’s baseline access supplied across its boundary. Adding that exposure to the regional comparison identifies a positive association with the 30-minute deficit share. A one-standard-deviation exposure increase corresponds to approximately 1.2 additional deficit percentage points.', 'This spatial accounting develops the policy question beyond a region’s own assignment. A payment reform can be assigned administratively while its relevant access network extends across borders. The evidence motivates evaluating those market connections alongside the average randomized contrast.')+F('jhe','t6')+note('Manuscript §VI.A.')),
    S('Connecting payment pressure to service readiness',P('The study builds a baseline proxy for the supply network’s readiness to support the home-dialysis incentives. It equals one minus the mean of the baseline shares of facilities offering peritoneal dialysis and home-hemodialysis training. A higher value describes a larger initial service gap.', 'The interaction between treatment and this proxy is +0.148, with a randomization p-value of 0.018. The analysis then adds rural composition, removes regions with unusual coverage or outcome movement, and separates the two service components. The table traces which parts of the baseline service configuration carry the association.', 'This extension makes a concrete connection between a reimbursement mechanism and the facilities needed to respond to it. It identifies a service-readiness dimension for linking future access studies to realized provider payment adjustments.')+F('jhe','t7')+note('Manuscript §VI.B.')));

  add('jfi',0,P('The descriptive starting point is a hedge that changes with the economic environment. When stock and bond returns move in opposite directions, a Treasury allocation offsets part of equity risk. When their shared news exposure turns positive, the same nominal allocation delivers a different risk outcome. The monthly average correlation shift of +0.377 therefore represents a change in the diversification input used by allocators.', 'The rolling series below shows how this relationship moves within and across regimes. It uses a 63-day window for daily stock–bond correlation, while the pre/post averages are computed from monthly realized correlations. These two views put the regime comparison in the context of substantial day-to-day and month-to-month variation.')+F('jfi','e1'));
  add('jfi',1,P('Synthetic Treasury returns keep maturity exposure comparable through time. The return approximation combines the yield’s carry with the first-order duration response and the second-order convexity term. Subtracting the one-month Treasury bill return puts the equity and bond sides on a common excess-return basis.', 'The three yield changes separate different dimensions of the news reaching markets: long real rates, the breakeven inflation spread and short nominal rates. Winsorization handles the tails of each daily change, and trailing standardization puts their coefficients on a comparable scale. The raw calendar contains 6,000 business days; differencing, the rolling window and complete-case merging produce the 5,245-observation baseline regression sample.')+steps([['Build the asset panel','Align the market, broad ETFs, industry portfolios and size–value portfolios with constant-maturity Treasury returns.'],['Construct the news proxies','Difference the yield series, winsorize their changes and standardize against trailing daily variation.'],['Estimate both regimes together','Interact each standardized news series with the post-2021 indicator, then recover the implied post-period loading.'],['Let exposures evolve','Fit a state-space representation to follow the covariance contribution of each channel through time.']])+note('Manuscript §2.'));
  add('jfi',2,P('The five headline baskets show how broad the change is even before the full cross section is considered. The market, capitalization-weighted SPY, equal-weighted RSP, growth-heavy QQQ and small-cap IWM all have negative real-rate interactions. The estimates range from −0.00335 for SPY to −0.00436 for IWM.', 'The channel comparison gives the result economic content. For each of those baskets, the real-rate interaction is the largest negative component. The inflation interaction is also negative, while the short-rate interaction is much closer to zero. A common factor-response change connects the different equity constructions.')+F('jfi','e2','e3'));
  add('jfi',3,P('For each channel, the time-varying stock loading is multiplied by the time-varying bond loading and the squared standardized news innovation. Aggregating these daily terms and normalizing by realized volatility expresses them on the same correlation scale as the observed stock–bond series.', 'The real-rate component crosses from a negative pre-period mean to a positive post-period mean. The inflation component becomes less negative, and the short-rate component contributes relatively little to the change. Exhibits 5 and 6 show the levels, differences and relative shares together, making the decomposition legible both numerically and visually.')+F('jfi','e5','e6'));
  add('jfi',4,P('Policy windows organize the same daily evidence by the Federal Reserve’s cycle. The pre-liftoff window, normalization, easing and COVID lower-bound period, hiking cycle, and subsequent hold-and-cut phase each imply a different setting for how equity prices respond to rate news.', 'The market loading is +0.00259 in 2005–2015 and +0.00024 in normalization. It is +0.00133 in the easing/COVID window, turns to −0.00238 during the hiking cycle, and reaches −0.00412 in the later hold-and-cut phase. These windows connect the pre/post result to the progression of the policy cycle.')+F('jfi','e12','e13'));
  add('jfi',5,P('The rule is deliberately easy to inspect. A 63-day rolling mean smooths the filtered market loading on the real-rate proxy. When that mean falls below −0.0015, the Treasury weight falls from 40% to 20%, with the difference held in cash. The equity weight remains 60%, so the portfolio exercise isolates the duration adjustment.', 'The wealth chart places the conditional portfolio next to static 60/40 and 100% equity. The lower panel records exactly when the conditional portfolio uses less duration. This makes the relationship between the estimated regime and the implemented allocation visible.', 'The most active later window is 2023–2025. Annualized volatility falls from 9.84% to 9.51%, with the same reported annual return of 1.67%. The full table also reports Sharpe ratios, maximum drawdowns and worst-quarter returns across all evaluation windows, allowing the risk change to be read alongside realized performance.')+F('jfi','e10','e11'));
  after('jfi','Real-rate news becomes bad news for equities',S('Testing the breadth of the equity response',P('The cross-sectional test expands the result to 23 equity baskets. In addition to the five headline series, it includes 12 industry portfolios and six size–book-to-market portfolios. Every real-rate interaction is negative, and every basket has a two-sided HAC p-value below 0.10.', 'This breadth links the result to market-wide repricing. The sign change appears across capitalization weights, firm sizes, styles and industries. The figure orders the estimated interactions so their common direction and cross-basket dispersion can be inspected at once.', 'For interpreting Treasury hedges, this matters because the equity side of a balanced portfolio is itself a portfolio. A response shared across many equity baskets is relevant to a wider range of asset mixes than a result concentrated in a single index.')+F('jfi','e4')+note('Manuscript §3.3.')));
  after('jfi','Accounting for the comovement shift',S('Locating the shift in time',P('The state-space model follows the market’s real-rate loading continuously. The smoothed path moves lower through 2022 and stays negative in the later post-2021 period. It provides a time profile behind the average interaction coefficient.', 'Separate post-period regressions sharpen that timing. The 2021 estimate is −0.00013, followed by −0.00153 in 2022 and −0.00415 in 2023–2025. The later estimate has a t-statistic of −4.29. This pattern places the strongest negative equity response after the tightening cycle is underway.', 'The two displays serve complementary purposes. The continuous path shows gradual evolution, and the subperiod estimates compare transparent date windows using the original regression framework.')+F('jfi','e7','e8')+note('Manuscript §§3.4–3.5.')));
  after('jfi','Following the policy cycle',S('Translating coefficients into portfolio magnitudes',P('The standardized regression coefficients can be translated into a familiar yield move. The full-sample winsorized standard deviation of the daily ten-year real-yield change is approximately 4.88 basis points. A ten-basis-point innovation therefore corresponds to approximately 2.05 standardized proxy units.', 'At that scale, the estimated equity response changes from +37.8 basis points before 2021 to −34.7 basis points afterward. The same conversion connects the change in correlation to the market-on-bond hedge ratio, which moves from approximately −0.97 to +0.11.', 'Exhibit 9 also translates the shift into the diversification delivered by a static 60/40 allocation. Its annualized volatility rises from approximately 10.7% to 11.3%, and its risk reduction relative to 100% equity falls from 44.1% to 36.3%. These magnitudes connect the econometric result to portfolio construction.')+`<div class="rm-widget" data-depth-widget="shock"><h3>Apply the same real-yield move in both regimes</h3><p>Scale the paper’s ten-basis-point comparison to inspect the change in equity response.</p><label>Real-yield increase: <output>10 bp</output><input type="range" min="0" max="20" step="1" value="10" aria-label="Real-yield increase in basis points"></label><div class="rm-output" aria-live="polite"></div></div>`+F('jfi','e9')+note('Manuscript §6.1 and Exhibit 9.')));
  after('jfi','From changing exposures to portfolio design',S('A research design built around competing explanations',P('The empirical sequence connects several layers of evidence. First, the observed stock–bond relationship supplies the outcome to explain. Second, the pooled interactions compare changes in the equity response to three distinct yield-based news proxies. Third, the cross section tests whether the result depends on the composition of one benchmark index. Fourth, time-varying and policy-window estimates establish when the response changes.', 'Treasury ETF checks supplement the synthetic bond-return construction with traded instruments at medium and long durations. The portfolio exercise then uses a filtered state estimate to connect the measured exposure to a transparent duration decision. Together, these elements turn a descriptive correlation break into a study of changing asset responses and their allocation consequences.')+focus('Treasury diversification is state dependent','The empirical contribution is to identify the equity real-rate response as a central component of the post-2021 hedge breakdown and to show how that response varies with the policy cycle.')+note('Manuscript §§4–6.')));
  M.jfi.limitation+=' The interactive yield-move explorer scales the rounded economic-magnitude estimates in Exhibit 9 linearly; it is an exposition of the reported coefficient conversion.';

  add('ijio',0,P('The timing of information is central. Users choose between Deep and Fast using the equilibrium service schedule. Only after the sale does the provider learn the request’s incremental compute cost and its profile of likely future evidence. The effort decision is therefore made with information that was unavailable when the buyer selected the product.', 'A common answer-release commitment makes this hidden margin possible. Productive computation takes time, but post-completion padding can fill the remaining interval. The visible waiting time is the sum of productive time and padding, so the same displayed delay can accompany different effort levels.')+steps([['Purchase','The user compares expected quality, price and waiting time.'],['Private information','The supplier learns the compute cost and evidence profile of the purchased request.'],['Hidden compute','The supplier chooses effort while maintaining the observable release commitment.'],['Public performance','A selected subset of outcomes enters the record that affects future sales.']]));
  add('ijio',2,P('The numerical economy makes the selection mechanism concrete. Average correctness is 0.6060 among Deep adopters and 0.6192 in the naturally observed evidence sample, a difference of 1.31 percentage points. The high-verifiability group accounts for 52.67% of adopters but 81.66% of observed outcomes.', 'The figure separates composition from performance. One panel shows who reaches the public record; another compares delivered and recorded accuracy; the third expands random outcome attestation while holding the underlying service schedule fixed. This shows exactly which part of the measured gap comes from selective visibility.')+F('ijio','f2'));
  add('ijio',3,P('Missing-evidence audits enter the supplier’s effort incentive. In the illustrated upper attracting branch, raising audit coverage increases effort on otherwise less-visible requests, closes the quality-allocation gap and increases Deep adoption. The four-panel display follows effort, incentive cutoffs, adoption and profit together.', 'This is a different experiment from adding representative observations after service is delivered. The first changes production incentives; the second changes how the resulting service is measured. Keeping those experiments separate gives verification policy a clear pair of objectives.')+F('ijio','f3'));
  after('ijio','The observable promise and the hidden choice',S('Solving the continuation-value feedback',P('Future selling opportunities give current effort its value. More credible service can attract adoption, which makes future exposure more valuable to preserve. The quality schedule induced by a conjectured continuation value must in turn generate that same value in equilibrium.', 'The numerical analysis solves this consistency relation as a fixed point. Figure 1 plots the induced-value map and the fixed-point residual, distinguishing roots that attract or repel under conjecture iteration. The branch structure gives a disciplined way to follow the response to audits, pricing and evidence opportunities.', 'Following a specified branch matters for interpreting the comparative statics. A change in monitoring can alter both the effort incentives within a branch and the set of equilibrium roots. The paper reports the numerical roots and residuals alongside the economic outcomes.')+F('ijio','f1')+note('Manuscript §5, Figure 1 and baseline-root calculations.')));

  add('geb',0,P('The value channel is economically legitimate at the original decision. Two people can face the same objective facts and rationally prefer different actions because their private circumstances differ. The source-aware user can separate the evidence in a recommendation from the adjustment made for those circumstances.', 'The source record gives that separation persistence. It attaches the reason for personalization to the saved recommendation, so later use can preserve the distinction between a factual signal and a value-dependent action adjustment. The model makes the amount of surviving provenance a platform choice.'));
  add('geb',2,P('The three panels separate outcomes that can move in different directions. The first measures current action loss, where personalization improves the original decision. The second measures future factual loss after reuse. The third combines the two dates with disclosure and audit costs into the full user-welfare comparison.', 'Intermediate reports can produce the highest future factual exposure because they combine a meaningful personalized component with incomplete corrective audit. At larger report magnitudes, audit incentives change again. This generates an exact interval of reports with greater future factual loss in the analyzed costly-audit environment.')+F('geb','f3'));
  add('geb',3,P('The platform chooses provenance before users choose their own disclosure and later audit. Its problem therefore anticipates behavioral responses at both dates. A planner values the resulting continuation losses fully, while the platform internalizes a specified fraction. The provenance comparison follows from that difference in the objective under the model’s curvature conditions.', 'The distribution of private types then translates a report-level result into population exposure. Figure 7 varies the tail growth of audit costs and the scale of the type distribution. The affected mass can change with both the behavioral response of an individual and the number of individuals placed in the relevant report interval.')+F('geb','f7'));
  after('geb','A two-date commitment game',S('Building the feasible technology frontier',P('The model connects effective factual precision and intended personalization through a primitive capacity technology. Allocating capacity to a stronger individualized adjustment changes the feasible precision available for factual inference. This gives the reduced-form advice rule an explicit production interpretation.', 'The frontier in Figure 1 is the feasible set used to organize technology comparisons. A capability change can move the economy along the frontier or change the frontier itself. Following that constraint makes the current-action and future-belief comparisons part of one technological environment.', 'The source-aware implementation at the first date identifies which component came from the private value. The later representation determines how much of that source information survives. The distinction between production and persistence is what lets improved current advice coexist with a different future factual outcome.')+F('geb','f1')+note('Manuscript §§2–3.')));

  add('portable',0,P('The two-period setting lets the platform’s design choice affect the assets users accumulate in the relationship. Records are information that can be exported. Specific skill is the user’s learned ability to operate the service, interpret its outputs and organize work around it. Product specialization changes the productive return and the portability of that learning.', 'The model follows these assets through the next period’s choice of provider. A design decision today changes both the value created inside the relationship and the loss associated with leaving it. This brings product design into the same analysis as price competition and switching.'));
  add('portable',1,P('The comparison matches the immediate switching-loss reduction at the existing design. This normalization makes the two interventions equally valuable to a user before the platform adjusts. Their different effects on the return to further specialization then determine the ranking of the design response.', 'In the fixed-recovery benchmark, skill recovery protects more of the next unit of relationship-specific learning. Its specialization response is therefore larger than that of an equally effective record export. Figure 1 follows finite improvements along this matched-relief comparison, extending the local derivative into a visible design path.')+F('portable','f1'));
  add('portable',3,P('Private practice creates a second adjustment margin. A user can invest effort in recovering the ability to use an exported record. Better recovery infrastructure replaces part of that effort, while a more valuable record changes the return to practicing. The design comparison therefore depends on how users reoptimize their own recovery.', 'The table reports economies on either side of the reversal threshold. The figure then varies direct record value and expresses each specialization response per unit of the intervention’s own fixed-design switching relief. Reading the normalization together with the endogenous effort choice explains why equal initial relief can lead to a different ranking.')+F('portable','t2','f2'));
  after('portable','Easier exit with more specialized products',S('Following both sides of the switching-loss calculation',P('Greater specialization raises the amount of relationship-specific value at stake, while portability restores part of that value after departure. The total switching loss reflects both movements. In the paper’s illustrated economy, moving from zero to full record coverage increases specialization from 0.2322 to 0.2763 while reducing the switching loss from 0.1057 to 0.0221.', 'The coexistence result is economically useful because specialization has a productive role. A more tailored product can become easier to leave when enough of its acquired value survives the move. Tracking only the specialization choice or only the direct export benefit would omit part of that adjustment.', 'Lifetime-surplus comparisons carry this logic through both periods. They combine the output created during the original relationship, the switching loss that remains afterward and the induced design response. This produces a policy comparison organized around the asset being restored.')+note('Manuscript Proposition 3, Table 1 and the lifetime-surplus analysis.')));

  add('contract',0,P('A routing class identifies which kind of goal the supplier is serving. Within that class, customers differ in private value and decide whether to accept the offered workflow. They can also verify its execution. The supplier chooses the workflow before observing that private value, and pays execution and preparation costs.', 'Billing capability determines the total prices that can be attached to those choices. A common action rate ties the classes together through one unit price. Class-specific rates can separate their bills. A goal-based price changes the billing unit, while a certificate changes which class or goal information can be used in contracting.')+F('contract','f1'));
  add('contract',1,P('The replacement argument asks whether a better workflow can keep the bill attached to the incumbent workflow. Holding the bill fixed preserves the customer’s price comparison while improving optimized value and lowering production costs. The supplier can then profitably replace the inferior implementation when the margin and feasibility conditions in the theorem hold.', 'This identifies the economically relevant contracting property: the set of feasible bills under replacement. With class-specific prices, action billing and goal billing can reproduce the same class-level total bills. The implementation result follows from that feasible set even though the invoice units look different.'));
  add('contract',3,P('An execution fee adds a pricing instrument and changes which customers adopt. The before-and-after welfare comparison therefore starts from a new equilibrium. In the adverse numerical example, welfare under action pricing begins at 0.333577 and ends at 0.285496; adding the execution fee lowers the initial level to 0.230877 while retaining the same final level.', 'The lower panels in Figure 3 display those levels directly. The upper panels report the corresponding changes in user surplus, welfare and correct goals. Keeping levels and changes side by side explains why the sign of the quality-improvement comparison can reverse after the contract is expanded.')+F('contract','f3'));
  add('contract',4,P('Discovery extends the analysis from a served goal to the number of goals the supplier can serve. Better technology can raise the profit available from each discovered opportunity, inducing additional investment. The welfare comparison depends on how that discovery response scales with investment cost.', 'The figure compares discovery technologies and cost responses. Exponential and hyperbolic discovery with power costs produce increasing response ratios in the illustrated cases. A separate strictly convex cost example yields a nonmonotone ratio, connecting the cutoff result to the specific elasticity restriction used in the theorem.')+F('contract','f4'));
  after('contract','Why a common rate can change the workflow',S('Separating technological efficiency from pricing incentives',P('A more reliable fine step changes the production possibilities available to the supplier. Under a common action rate, the low-value market can constrain that rate, while a longer workflow raises the total bill paid by a higher-value class. Workflow length consequently serves both a production role and a pricing role.', 'The numerical economies trace what happens when the supplier reoptimizes after quality improves. The resulting changes include adoption, user verification, completed goals, profit and welfare. Following all these margins makes it possible to identify a privately attractive workflow change that reduces total economic value.', 'The contract comparison then changes the feasible pricing instruments while retaining the underlying goal technology. This isolates how the billing architecture mediates the economic value of technical progress.')+note('Manuscript common-rate analysis and numerical economies.')));

  add('archives',0,P('Each archived version combines useful learning with exposure to a nuisance component. Those loadings can improve at different speeds, so a newer version changes the composition of information as well as its standalone accuracy. An institution chooses a nonnegative mixture before the future signal innovations arrive.', 'The dealer observes the chosen information law and prices aggregate order flow. Institutions anticipate both trading rents and the price impact of their information choice. A real investor then uses the market price in an investment decision. This sequence connects research deployment to both market informativeness and real economic value.'));
  add('archives',2,P('With unequal learning speeds, mixtures span a two-dimensional archive. The relevant boundary records the information compositions attainable by combining versions. In the two-institution benchmark, outward radial improvements place private best responses and efficient deployments on that boundary, so at most two versions implement each relevant choice.', 'Figure 1 shows the geometry before and after correction. Private deployment and efficient deployment occupy different positions in the archive. Correction changes the available signals and the versions selected from them, so the comparison lets both institutions and the planner reoptimize their deployment.')+F('archives','f1'));
  add('archives',3,P('The planner compares the investment value of price information with the real cost of correction. Institutions compare that same service with the extra trading return it permits. The model evaluates correction after allowing each side to choose its preferred archive, making the expenditure difference a joint choice over signal improvement and deployment.', 'Figure 3 places the private purchase regions next to the planner’s value envelope. There is a range in which both institutions purchase correction even though the corresponding corrected profile has lower net social value than the uncorrected private profile. Figure 4 then changes noise-order variance to trace how that range develops.')+F('archives','f3','f4'));
  after('archives','Three objectives, three deployment choices',S('Why information aggregation changes the preferred archive',P('Standalone signal information evaluates a forecast in isolation. Price information evaluates what survives strategic trading and aggregation with another institution’s order. When errors are correlated, a component that improves an institution’s own forecast can also increase the common nuisance carried into aggregate order flow.', 'Private trading incentives sit between those two information objectives under the archive-ordering result’s path conditions. The institution values differentiation from its rival but also captures rents from its own information. The ordering therefore follows from the interaction of signal composition, strategic trading and common error.', 'The framework also separates the deployment distortion from correction spending. In the independent-error two-institution benchmark, archive choice can be informationally efficient while the private incentive to buy correction remains excessive. The distinction identifies two different margins for evaluating research technology.')+note('Manuscript archive-ordering, boundary and correction results.')));

  add('resource-coupling',0,P('Resource rights affect the incentive to imitate a committed partner. Settling those rights changes what a participant can gain from keeping the team together and releases capacity for further investment. The organizer chooses settlements and an information procedure before the participants make the continuation decision.', 'The exact reciprocal-continuation benchmark selects the team when both participants have high continuation values. Verification reveals resource exposure, while the costly investment still communicates willingness to continue. This separates checkable resource information from privately held preferences for the team.'));
  add('resource-coupling',2,P('The local interaction has a direct organizational interpretation. A check changes the settlement appropriate for one participant. If checking both participants moves their settlements in the same direction, the shared interface becomes easier to adjust jointly. If their settlement changes oppose each other, joint verification exposes a more costly disagreement.', 'This sign result explains why coupling can generate either complementarity or substitution. The value of a check depends on the action it enables and how that action combines with the other participant’s adjustment. Resource architecture is therefore part of the information-acquisition problem.'));
  add('resource-coupling',3,P('The computed program changes with the strength of coupling. At moderate coupling, the organizer can inspect one participant first and make the second inspection conditional on the result. Near the common-settlement limit, paired checking becomes more attractive because an unchecked module can constrain the joint adjustment.', 'The modularization comparison then asks whether the organizer should change that interface. In the displayed economy, the gross redesign gain is positive with verification and zero without it. Information makes differentiated settlements useful, and redesign reduces the cost of implementing those differences.')+F('resource-coupling','t3','t4'));
  add('resource-coupling',4,P('Allowing continuation errors changes the optimization problem. The organizer can trade a small probability of selecting the wrong team against the value of using information earlier. The displayed frontier jointly reoptimizes settlement, timing and the relevant cutoff equilibrium as the permitted error rate changes.', 'The table records the feasible value, false-positive and false-negative rates, continuation probability and selected disclosure schedule. Reading these together connects the information timing choice to the outcomes it implements, and shows how a different continuation objective changes the preferred procedure.')+F('resource-coupling','t7'));
  after('resource-coupling','A cost function that spans organizational designs',S('From individual checks to an adaptive program',P('A verification program specifies which participant is checked first, whether the second check depends on the first result, and which settlements follow each information history. The paper compares eight pure adaptive procedures and their mixtures. Each procedure is evaluated through the continuation allocation and resource cost it implements.', 'Workload adds another dimension. Paired checking and independent checking can have the same average coverage while producing different realized inspection loads. With convex workload costs, concentrating inspections in the same cases changes the program’s cost.', 'The organizer therefore balances the information gained from paired records against the cost of obtaining and using those records together. Conditional checking can save an inspection when the first result makes the remaining record less valuable or avoids an expensive joint adjustment.')+note('Manuscript verification procedures, workload and coupling analysis.')));

  M.mortgage={
    lead:'A lending decision hides the outcome needed to evaluate it. This study links mortgage applications to loan performance at the risk-cell level, bounds the repayment risk of denied borrowers, and maps the assumptions under which expanding credit improves worst-case welfare.',
    sections:[
      S('The selective-labels problem in mortgage lending',P('Repayment performance is observed after a mortgage is originated. For a denied applicant, the repayment outcome under approval remains unobserved. The paper targets precisely that counterfactual: the default rate denied applicants would have experienced if they had received loans.', 'The empirical question is organized around sensitivity. How much additional hidden risk would denied applicants need to carry before the policy conclusion changes? This makes the relationship between selection assumptions and lending decisions explicit, using a linked administrative data construction and a minimax policy objective.')+steps([['Observe applications','HMDA supplies application decisions and borrower and loan characteristics.'],['Observe performance','Freddie Mac supplies repayment outcomes for originated loans.'],['Link risk cells','Combine the sources using common observable characteristics.'],['Bound and optimize','Map counterfactual risk intervals into worst-case lending decisions.']])),
      S('Building a common risk-cell sample',P('The analysis uses 2018–2022 mortgage cohorts with 2019 excluded from the main specification because COVID forbearance affects the performance measure. The linkage groups records by year, state, loan amount, debt-to-income ratio and combined loan-to-value ratio.', 'The main matched-support specification contains 11,136 risk cells, approximately 10.0 million applications and 623,090 denied applicants. Performance is aggregated within cells and reweighted to describe the denied population. The two data sources contribute different pieces of the counterfactual comparison: the distribution of denied applications and the observed risk of originated loans in comparable cells.', 'Coverage is tracked as part of the sample construction, and the paper reports alternatives that change the matching threshold and treatment of cells outside the supported sample.')+note('Manuscript §3 and Tables 1–3, 8.')),
      S('From selection assumptions to a risk interval',P('The assumption ladder begins with the unrestricted [0,1] risk interval. Monotone selection places denied applicants at least as high in risk as approved borrowers in the same cell. A bounded adverse-selection parameter κ then caps the additional default probability.', 'At κ = 0.10, the denied-weighted main-sample interval is approximately [0.023, 0.123]. The table shows how that interval changes with the cohort and supported population. The parameter is kept visible throughout the analysis so the policy exercise can be read as a comparison across possible degrees of hidden selection.', 'A second parameter, δS, describes the gap between Freddie-observed performance and the broader originated population. This transport layer separates uncertainty about the performance source from uncertainty about denied applicants themselves.')+F('mortgage','t3')+note('Manuscript §§2–4.')),
      S('Benchmarking the observed screening gradient',P('The observed data give a useful benchmark for the scale of the sensitivity analysis. Across denial-rate quintiles, default rates for originated loans rise from approximately 0.9% to 3.1%, a gradient of 2.2 percentage points. Denial rates rise much more sharply across those same groups.', 'Figure 4 puts those two gradients on the same ordered set of cells. The default gradient is roughly one-fifth of a ten-percentage-point adverse-selection gap. That comparison gives an empirical scale for interpreting the amount of hidden risk required by the lending-policy analysis.', 'The paper also examines debt-to-income and loan-to-value groups, then extends the bound calculations across geographies and race–ethnicity groups. These decompositions show how the administrative linkage can be used to inspect the risk comparison across observable parts of the market.')+F('mortgage','f4')),
      S('Optimizing lending under worst-case default risk',P('The policy problem chooses cell-level approval decisions using the upper risk bound and a specified welfare payoff for lending. The benchmark parameters are a mortgage spread of 0.02, loss given default of 0.35 and a fixed default cost of 0.005. The optimization traces the approval policy that maximizes welfare under the least favorable default rates in the identified set.', 'At κ = 0.10 and zero transport gap, the reported optimal approval rate is 96.4%, compared with 93.8% in the matched-sample status quo. At a one-percentage-point transport gap, the optimal rate is 94.9%. The linear-program relaxation yields nearly binary policies, making the allocation interpretable as a set of cell-level lending decisions.', 'Alternative welfare parameters and coverage thresholds are reported alongside the central specification. This connects the recommendation implied by the model to the economic payoffs used to evaluate it.')+note('Manuscript §5 and Tables 7–10.')),
      S('Mapping the breakdown frontier',P('The two-dimensional map varies adverse selection and transport uncertainty together. Each point re-solves the lending problem, and the black contour records where the optimal approval rate equals the 93.8% status quo. Crossing that contour changes the direction of the policy comparison.', 'The strongest movement in the displayed approval rate runs along the transport dimension. A larger gap between Freddie-observed and population default rates raises worst-case lending costs throughout the supported market. Under the benchmark welfare objective, this becomes the binding sensitivity margin for the policy conclusion.', 'The result gives the next data investment a concrete direction: better linkage to the repayment performance of the broader originated population would sharpen the transport comparison and the policy frontier.')+F('mortgage','f3')),
      S('The empirical and methodological contribution',P('The study combines a large application universe, loan-performance records and an explicit sensitivity framework. Its output is a map from assumptions about missing outcomes to credit-allocation decisions. The contribution lies in making that map inspectable at the risk-cell level and in separating selection from transport uncertainty.', 'This approach is useful whenever the observed outcome depends on an earlier screening decision. Linking the data construction, bound calculation and policy objective makes each stage of that decision problem visible to the reader.'))
    ],
    limitation:'The linkage is at the risk-cell level, not the individual borrower level. Counterfactual intervals depend on monotone selection, the adverse-selection bound and the transport sensitivity parameter. Their width at a fixed κ is imposed by that assumption. Policy comparisons depend on the stated welfare parameters and matched support; the observed screening gradient is a descriptive benchmark, not an estimate of the unobserved denied-group risk gap. The 2019 cohort is excluded in the main specification because of pandemic-related performance contamination.'
  };
  window.__researchDepth={figure:F,paragraphs:P,section:S,steps,focus};
})();
